const body = $input.first().json.body || {};
return [{ json: {
  docId: 'cRP1WgZQv7KmwmVrUbuEF8',
  userId: Number(body.userId),
  cardId: Number(body.cardId),
  fromQuality: (body.fromQuality || 'damaged').toString(),
  // Controle total (2026-10-02) : exemplaires EXACTS a consommer, et celui
  // dont le numero de serie est conserve sur le nouvel exemplaire.
  pullIds: Array.isArray(body.pullIds) ? body.pullIds.map(Number).filter((n) => Number.isInteger(n) && n > 0) : [],
  keepPullId: body.keepPullId != null ? Number(body.keepPullId) : null
} }];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const allPulls = $('Get Pulls').all().map((i) => i.json).filter((r) => r.id != null && !r.InVault); // coffre perso : cartes protegees exclues
const cards = $('Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
const card = cards.find((c) => c.id === cfg.cardId);
const configRow = $('Get Config').all().map((i) => i.json).find((r) => r.id != null);
const REQUIRED_COUNT = (configRow && configRow.QualityRepairCost) || 3;

if (!card) return [{ json: { ok: false, error: 'card_not_found' } }];
if (card.IsPromo) return [{ json: { ok: false, error: 'promo_not_repairable' } }];
if (card.Active === false) return [{ json: { ok: false, error: 'card_inactive' } }];

// Echelle de qualite fixe, du plus abime au plus parfait. Chaque palier
// consomme REQUIRED_COUNT exemplaires IDENTIQUES (meme carte, meme qualite,
// reglable dans Equilibrage du jeu - defaut 3) pour en produire 1 seul de
// la qualite suivante - deterministe, pas de RNG (meme principe que la
// fusion de finitions, juste une echelle plus courte).
const QUALITY_ORDER = ['damaged', 'worn', 'good', 'mint'];
const fromIndex = QUALITY_ORDER.indexOf(cfg.fromQuality);
if (fromIndex === -1 || fromIndex === QUALITY_ORDER.length - 1) {
  return [{ json: { ok: false, error: 'invalid_quality' } }];
}
const toQuality = QUALITY_ORDER[fromIndex + 1];

function qualityOf(p) { return p.Quality || 'damaged'; }
const myPulls = allPulls.filter((p) => refId(p.User) === cfg.userId);
const matching = myPulls.filter((p) => refId(p.Card) === cfg.cardId && qualityOf(p) === cfg.fromQuality);
if (matching.length < REQUIRED_COUNT) {
  return [{ json: { ok: false, error: 'not_enough_duplicates' } }];
}

// Plus de quota (Cards.MaxSerial) : la carte restauree reste attribuable
// indefiniment. On suit QUELS numeros sont utilises (pas juste un
// compteur) pour reattribuer le plus petit numero libre - un exemplaire
// decrafte/defausse libere vraiment son numero pour une future
// restauration.
const usedSerials = new Set();
allPulls.forEach((p) => { if (refId(p.Card) === cfg.cardId && p.SerialNumber != null) usedSerials.add(p.SerialNumber); });
let serialNumber = null;
for (let n = 1; ; n++) { if (!usedSerials.has(n)) { serialNumber = n; break; } }


const FINISH_RANK = ['normal', 'holo', 'gold', 'ghost', 'diamond', 'rainbow'];
function otherRank(p) { return FINISH_RANK.indexOf(p.Finish || 'normal'); }
let consumed;
if (cfg.pullIds.length) {
  const uniq = [...new Set(cfg.pullIds)];
  if (uniq.length !== REQUIRED_COUNT) return [{ json: { ok: false, error: 'wrong_selection_count' } }];
  consumed = uniq.map((id) => matching.find((p) => p.id === id));
  if (consumed.some((p) => !p)) return [{ json: { ok: false, error: 'invalid_selection' } }];
} else {
  consumed = [...matching].sort((a, b) =>
    (otherRank(a) - otherRank(b)) || ((b.SerialNumber || 0) - (a.SerialNumber || 0))
  ).slice(0, REQUIRED_COUNT);
}
let keepPull = null;
if (cfg.keepPullId != null) {
  keepPull = consumed.find((p) => p.id === cfg.keepPullId);
  if (!keepPull) return [{ json: { ok: false, error: 'invalid_keep' } }];
} else {
  keepPull = consumed.filter((p) => p.SerialNumber != null).sort((a, b) => a.SerialNumber - b.SerialNumber)[0] || null;
}
// Le numero conserve est libere par la suppression de son exemplaire : on
// le reattribue au nouvel exemplaire. A defaut (aucun numero), le plus petit
// numero libre comme avant.
if (keepPull && keepPull.SerialNumber != null) serialNumber = keepPull.SerialNumber;
const pullIdsToDelete = consumed.map((p) => p.id);

// BUG REEL corrige ici (2026-09-29) : la ligne recreee n'ecrivait jamais
// Finish, donc Grist la laissait vide (= 'normal' partout ailleurs dans le
// code) - restaurer la qualite effacait silencieusement la finition de la
// carte. Les 3 exemplaires consommes peuvent avoir des finitions
// differentes (le filtre ne matche que sur la qualite) : on reporte la
// PLUS PRESTIGIEUSE d'entre elles sur le nouvel exemplaire, pour ne jamais
// faire perdre de valeur au joueur.
const FINISH_ORDER_R = ['normal', 'holo', 'gold', 'ghost', 'diamond', 'rainbow'];
function finishOfR(p) { return p.Finish || 'normal'; }
const finish = consumed.reduce((best, p) => {
  const f = finishOfR(p);
  return FINISH_ORDER_R.indexOf(f) > FINISH_ORDER_R.indexOf(best) ? f : best;
}, 'normal');

// Niveaux de profil : XP gagnee pour une restauration reussie (meme montant
// que crafter une carte), +1 booster bonus par niveau franchi.
const users = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const user = users.find((u) => u.id === cfg.userId);
function levelForXp(xp) { xp = xp || 0; return Math.floor((25 + Math.sqrt(625 + 100 * xp)) / 50); }
const XP_PER_REPAIR = 5;
const oldXp = (user && user.XP) || 0;
const newXp = oldXp + XP_PER_REPAIR;
const levelsGained = levelForXp(newXp) - levelForXp(oldXp);
const newBoosterCount = ((user && user.BoosterCount) || 0) + levelsGained;

return [{ json: {
  ok: true,
  userId: cfg.userId,
  newXp,
  newBoosterCount,
  docId: cfg.docId,
  cardId: cfg.cardId,
  pullIdsToDelete,
  fromQuality: cfg.fromQuality,
  toQuality,
  obtainedAt: Math.floor(Date.now() / 1000),
  batchId: `quality-${cfg.userId}-${Date.now()}`,
  serialNumber,
  finish
} }];

const r = $('Compute Repair').first().json;
return [{ json: {
  repaired: true,
  cardId: r.cardId,
  fromQuality: r.fromQuality,
  toQuality: r.toQuality,
  serialNumber: r.serialNumber,
  finish: r.finish
} }];
